from __future__ import annotations
import random, sqlite3
from pathlib import Path
import numpy as np
import pandas as pd
SEED=42; DEFAULT_ACCESSIONS=25_000; ROOT=Path(__file__).resolve().parents[1]; GENERATED_DIR=ROOT/'data'/'generated'; DATABASE_PATH=ROOT/'database'/'lab_revenue_cycle.db'; SCHEMA_PATH=ROOT/'database'/'schema.sql'; AS_OF_DATE=pd.Timestamp('2026-10-31')
REGIONS=['Northeast','Southeast','Midwest','West']; CALL_POINTS=['Primary Care (PCP)','Multispecialty','Federally Qualified Health Centers (FQHC)','Cardiology','Neurology','OB/GYN']
TEST_ROWS=[('80053','Comprehensive Metabolic Panel','General Health & Wellness',68.0,['E11.9','I10','Z00.00','R53.83']),('85025','Complete Blood Count','General Health & Wellness',42.0,['D64.9','R53.83','Z00.00']),('83036','Hemoglobin A1c','Cardiometabolic',49.0,['E11.9','R73.03']),('80061','Lipid Panel','Cardiometabolic',61.0,['E78.5','I10','Z00.00']),('84443','Thyroid Stimulating Hormone','General Health & Wellness',58.0,['E03.9','R53.83']),('82728','Ferritin','Women’s Health',55.0,['D64.9','R53.83']),('82306','Vitamin D','Women’s Health',86.0,['E55.9','R53.83']),('82607','Vitamin B12','Neurology',63.0,['D64.9','R53.83']),('84153','PSA','Oncology',78.0,['Z12.5','R97.20']),('86308','Heterophile Antibody','Infectious Disease',47.0,['B27.90','R50.9']),('87591','Chlamydia NAAT','Infectious Disease',92.0,['Z11.3','A74.9']),('87491','Gonorrhea NAAT','Infectious Disease',92.0,['Z11.3','A54.9'])]
DIAGNOSIS_DESCRIPTIONS={'E11.9':'Type 2 diabetes mellitus without complications','I10':'Essential hypertension','Z00.00':'General adult examination','R53.83':'Other fatigue','D64.9':'Anemia unspecified','R73.03':'Prediabetes','E78.5':'Hyperlipidemia unspecified','E03.9':'Hypothyroidism unspecified','E55.9':'Vitamin D deficiency unspecified','Z12.5':'Screening for malignant neoplasm of prostate','R97.20':'Elevated prostate specific antigen','B27.90':'Infectious mononucleosis without complication','R50.9':'Fever unspecified','Z11.3':'Screening for infections with a predominantly sexual mode of transmission','A74.9':'Chlamydial infection unspecified','A54.9':'Gonococcal infection unspecified'}
PAYER_ROWS=[('PAY001','UnitedHealthcare','UnitedHealthcare','UnitedHealthcare Commercial','Commercial',120,1.00),('PAY002','Aetna','CVS Health','Aetna Commercial','Commercial',120,1.05),('PAY003','Cigna Healthcare','The Cigna Group','Cigna Commercial','Commercial',120,.96),('PAY004','Anthem','Elevance Health','Anthem Commercial','Commercial',120,1.08),('PAY005','Humana','Humana','Humana Medicare Advantage','Medicare Advantage',180,1.12),('PAY006','Kaiser Permanente','Kaiser Permanente','Kaiser Commercial','Commercial',120,.90),('PAY007','HCSC','Health Care Service Corporation','HCSC Commercial','Commercial',120,1.03),('PAY008','Centene','Centene','Centene Medicaid Managed Care','Medicaid Managed Care',180,1.16),('PAY009','Molina Healthcare','Molina Healthcare','Molina Medicaid Managed Care','Medicaid Managed Care',180,1.18),('PAY010','Highmark','Highmark Health','Highmark Commercial','Commercial',120,1.02),('PAY011','Independence Blue Cross','Independence Health Group','Independence Blue Cross Commercial','Commercial',120,.98),('PAY012','Horizon Blue Cross Blue Shield of New Jersey','Horizon BCBSNJ','Horizon Commercial','Commercial',120,1.01),('PAY013','Florida Blue','GuideWell','Florida Blue Commercial','Commercial',120,1.04),('PAY014','Blue Shield of California','Blue Shield of California','Blue Shield of California Commercial','Commercial',120,.94),('PAY015','Blue Cross Blue Shield of Michigan','BCBSM','BCBSM Commercial','Commercial',120,1.00),('PAY016','CareFirst BlueCross BlueShield','CareFirst','CareFirst Commercial','Commercial',120,1.06),('PAY017','Traditional Medicare','CMS','Traditional Medicare','Traditional Medicare',365,.88),('PAY018','Traditional Medicaid','State Medicaid Programs','Traditional Medicaid','Traditional Medicaid',180,1.10)]
def identifiers(prefix,count,width=7): return [f'{prefix}{i:0{width}d}' for i in range(1,count+1)]
def make_tests(): return pd.DataFrame([(c,n,f,p) for c,n,f,p,_ in TEST_ROWS],columns=['test_code','test_name','franchise','base_charge'])
def make_diagnoses(): return pd.DataFrame(list(DIAGNOSIS_DESCRIPTIONS.items()),columns=['diagnosis_code','diagnosis_description'])
def make_payers(): return pd.DataFrame(PAYER_ROWS,columns=['payer_id','payer_name','parent_organization','operating_plan','line_of_business','filing_limit_days','denial_factor'])
def make_patients(rng,count): return pd.DataFrame({'patient_id':identifiers('PT',count),'birth_year':rng.integers(1935,2009,count),'sex':rng.choice(['F','M','X'],count,p=[.505,.485,.01])})
def make_providers(rng,count=650): return pd.DataFrame({'provider_id':identifiers('PR',count,5),'region':rng.choice(REGIONS,count,p=[.38,.24,.20,.18]),'call_point':rng.choice(CALL_POINTS,count,p=[.31,.18,.12,.17,.10,.12])})
def make_clients(rng,count=220): return pd.DataFrame({'client_account_id':identifiers('CLI',count,5),'region':rng.choice(REGIONS,count,p=[.38,.24,.20,.18]),'call_point':rng.choice(CALL_POINTS,count,p=[.31,.18,.12,.17,.10,.12])})
def make_accessions(rng,patients,providers,clients,payers,count):
    dates=AS_OF_DATE-pd.to_timedelta(rng.integers(0,365,count),unit='D'); lookup={c:(n,f,p,dx) for c,n,f,p,dx in TEST_ROWS}; codes=rng.choice(list(lookup),count); base=np.array([lookup[c][2] for c in codes]); diagnosis=np.array([rng.choice(lookup[c][3]) for c in codes],dtype=object); missing=rng.random(count)<.025; malformed=(~missing)&(rng.random(count)<.012); unsupported=(~missing)&(~malformed)&(rng.random(count)<.035); all_dx=list(DIAGNOSIS_DESCRIPTIONS); diagnosis[missing]=None; diagnosis[malformed]=rng.choice(['BADCODE','123.XX','E11..9'],malformed.sum())
    for i in np.where(unsupported)[0]: diagnosis[i]=rng.choice([x for x in all_dx if x not in set(lookup[codes[i]][3])])
    client_ids=rng.choice(clients.client_account_id,count); cm=clients.set_index('client_account_id'); frame=pd.DataFrame({'accession_id':identifiers('ACC',count),'patient_id':rng.choice(patients.patient_id,count),'client_account_id':client_ids,'provider_id':rng.choice(providers.provider_id,count),'payer_id':rng.choice(payers.payer_id,count),'service_date':dates.strftime('%Y-%m-%d'),'collection_date':dates.strftime('%Y-%m-%d'),'test_code':codes,'diagnosis_code':diagnosis,'charge_amount':np.round(base*rng.uniform(.92,1.14,count),2)}); frame['region']=[cm.loc[x,'region'] for x in client_ids]; frame['call_point']=[cm.loc[x,'call_point'] for x in client_ids]; frame['accession_status']=np.where(missing|malformed,'Billing review','Ready for billing'); return frame
def make_eligibility(rng,a):
    n=len(a); checked=pd.to_datetime(a.service_date)-pd.to_timedelta(rng.integers(0,4,n),unit='D'); return pd.DataFrame({'eligibility_id':identifiers('ELG',n),'accession_id':a.accession_id,'coverage_status':rng.choice(['Active','Inactive','Unable to verify'],n,p=[.94,.04,.02]),'subscriber_match':rng.choice(['Match','Mismatch','Missing'],n,p=[.96,.027,.013]),'authorization_status':rng.choice(['Not required','Present','Missing'],n,p=[.74,.235,.025]),'checked_date':checked.dt.strftime('%Y-%m-%d')})
def make_claims(rng,a,e,p):
    x=a.merge(e,on='accession_id').merge(p[['payer_id','denial_factor']],on='payer_id'); ok=x.coverage_status.eq('Active')&x.subscriber_match.eq('Match')&x.authorization_status.ne('Missing')&x.accession_status.eq('Ready for billing'); x=x.loc[ok].reset_index(drop=True); n=len(x); submitted=pd.to_datetime(x.service_date)+pd.to_timedelta(rng.integers(1,13,n),unit='D'); allowed=np.round(x.charge_amount.to_numpy()*rng.uniform(.42,.78,n),2); expected=np.round(allowed*rng.uniform(.82,.98,n),2); denied=rng.random(n)<np.clip(.085*x.denial_factor.to_numpy()*rng.uniform(.85,1.15,n),.035,.18); return pd.DataFrame({'claim_id':identifiers('CLM',n),'accession_id':x.accession_id,'submission_date':submitted.dt.strftime('%Y-%m-%d'),'claim_type':'Original','charge_amount':x.charge_amount,'allowed_amount':allowed,'expected_reimbursement':expected,'payment_amount':np.where(denied,0,expected),'claim_status':np.where(denied,'Denied','Paid'),'original_claim_id':None})
def make_denials(rng,c,a):
    x=c[c.claim_status.eq('Denied')].merge(a[['accession_id','diagnosis_code']],on='accession_id').reset_index(drop=True); n=len(x); cats=rng.choice(['Eligibility','Diagnosis documentation','Authorization','Duplicate claim','Medical necessity','Timely filing','Other administrative'],n,p=[.20,.24,.12,.10,.13,.08,.13]); reason={'Eligibility':'SIM ELIG','Diagnosis documentation':'SIM DX','Authorization':'SIM AUTH','Duplicate claim':'SIM DUP','Medical necessity':'SIM MED','Timely filing':'SIM TIME','Other administrative':'SIM ADMIN'}; dates=pd.to_datetime(x.submission_date)+pd.to_timedelta(rng.integers(7,31,n),unit='D'); resolution=rng.choice(['Recovered','Pending','Written off'],n,p=[.54,.31,.15]); rdates=dates+pd.to_timedelta(rng.integers(4,61,n),unit='D'); rtext=rdates.dt.strftime('%Y-%m-%d').astype(object); rtext[resolution=='Pending']=None; recovered=np.where(resolution=='Recovered',np.round(x.expected_reimbursement.to_numpy()*rng.uniform(.65,1,n),2),0); return pd.DataFrame({'denial_id':identifiers('DEN',n),'claim_id':x.claim_id,'denial_category':cats,'simulated_reason_code':[reason[v] for v in cats],'diagnosis_related':np.isin(cats,['Diagnosis documentation','Medical necessity']),'denial_date':dates.dt.strftime('%Y-%m-%d'),'denied_amount':x.expected_reimbursement,'resolution_status':resolution,'resolution_date':rtext,'recovered_amount':recovered})
def make_work_queue(rng,a,e,p):
    x=a.merge(e,on='accession_id').merge(p[['payer_id','filing_limit_days']],on='payer_id'); q=x.loc[x.accession_status.eq('Billing review')|x.coverage_status.ne('Active')|x.subscriber_match.ne('Match')|x.authorization_status.eq('Missing')].copy().reset_index(drop=True); q['exception_type']=np.select([q.accession_status.eq('Billing review'),q.coverage_status.ne('Active'),q.subscriber_match.ne('Match')],['Diagnosis or documentation review','Eligibility review','Subscriber information review'],default='Authorization review'); service=pd.to_datetime(q.service_date); remaining=((service+pd.to_timedelta(q.filing_limit_days,unit='D'))-AS_OF_DATE).dt.days; age=(AS_OF_DATE-service).dt.days; resolvability=np.round(rng.uniform(.42,.92,len(q)),2); priority=np.round(np.clip((60-remaining)/60,0,1)*45+np.clip(q.charge_amount/120,0,1)*30+resolvability*25,2); status=rng.choice(['Pending review','Documentation requested','Awaiting provider response','Corrected','Resubmitted','Resolved'],len(q),p=[.30,.18,.15,.12,.10,.15]); return pd.DataFrame({'work_item_id':identifiers('WQ',len(q)),'accession_id':q.accession_id,'exception_type':q.exception_type,'priority_score':priority,'queue_status':status,'created_date':service.dt.strftime('%Y-%m-%d'),'follow_up_date':(service+pd.to_timedelta(rng.integers(2,15,len(q)),unit='D')).dt.strftime('%Y-%m-%d'),'resolution_probability':resolvability,'exception_age_days':age,'days_to_filing':remaining,'financial_exposure':q.charge_amount})
def make_claim_history(c,d):
    rows=[]; i=1
    for r in c.itertuples(index=False): rows.append((f'EVT{i:08d}',r.claim_id,'Submitted',r.submission_date,'Synthetic original claim submitted')); i+=1
    for r in d.itertuples(index=False): rows.append((f'EVT{i:08d}',r.claim_id,'Denied',r.denial_date,f'Synthetic denial category {r.denial_category}')); i+=1
    return pd.DataFrame(rows,columns=['event_id','claim_id','event_type','event_date','notes'])
def build_dataset(accession_count=DEFAULT_ACCESSIONS):
    random.seed(SEED); rng=np.random.default_rng(SEED); patients=make_patients(rng,max(8000,int(accession_count*.58))); providers=make_providers(rng); clients=make_clients(rng); payers=make_payers(); tests=make_tests(); diagnoses=make_diagnoses(); accessions=make_accessions(rng,patients,providers,clients,payers,accession_count); eligibility=make_eligibility(rng,accessions); claims=make_claims(rng,accessions,eligibility,payers); denials=make_denials(rng,claims,accessions); work_queue=make_work_queue(rng,accessions,eligibility,payers); claim_history=make_claim_history(claims,denials); return {'patients':patients,'providers':providers,'clients':clients,'payers':payers,'tests':tests,'diagnoses':diagnoses,'accessions':accessions,'eligibility':eligibility,'claims':claims,'denials':denials,'work_queue':work_queue,'claim_history':claim_history}
def write_outputs(tables):
    GENERATED_DIR.mkdir(parents=True,exist_ok=True); DATABASE_PATH.parent.mkdir(parents=True,exist_ok=True)
    for n,f in tables.items(): f.to_csv(GENERATED_DIR/f'{n}.csv',index=False)
    if DATABASE_PATH.exists(): DATABASE_PATH.unlink()
    with sqlite3.connect(DATABASE_PATH) as con:
        con.executescript(SCHEMA_PATH.read_text())
        for n,f in tables.items(): f.to_sql(n,con,if_exists='append',index=False)
if __name__=='__main__':
    t=build_dataset(); write_outputs(t); print(f"Generated {len(t['accessions']):,} synthetic accessions and {len(t['claims']):,} claims")
